  ('DOC014-C1', 'DOC014', 1, 'Total Knee Replacement Discharge Instructions', 'Orthopedics', 'discharge_instructions', '2026-03-15', 'Total Knee Replacement Discharge Instructions. Your goal is to bend your new knee to 90 degrees within 2 weeks. Do the home exercises 3 times a day.'),
  ('DOC014-C2', 'DOC014', 2, 'Total Knee Replacement Discharge Instructions', 'Orthopedics', 'discharge_instructions', '2026-03-15', 'Total Knee Replacement Discharge Instructions. Ice your knee for 20 minutes at a time, several times a day, with a cloth between the ice and your skin.'),
  ('DOC014-C3', 'DOC014', 3, 'Total Knee Replacement Discharge Instructions', 'Orthopedics', 'discharge_instructions', '2026-03-15', 'Total Knee Replacement Discharge Instructions. Outpatient physical therapy is 3 times a week for 6 to 8 weeks.'),
  ('DOC014-C4', 'DOC014', 4, 'Total Knee Replacement Discharge Instructions', 'Orthopedics', 'discharge_instructions', '2026-03-15', 'Total Knee Replacement Discharge Instructions. Call your surgeon right away for new calf pain, calf swelling or a fever over 101 F.'),
  ('DOC015-C1', 'DOC015', 1, 'Cast Care at Home', 'Orthopedics', 'patient_education', '2025-10-10', 'Cast Care at Home. Keep your cast dry. Cover it with a plastic bag to shower. Never push objects like coat hangers inside the cast to scratch.'),
  ('DOC015-C2', 'DOC015', 2, 'Cast Care at Home', 'Orthopedics', 'patient_education', '2025-10-10', 'Cast Care at Home. Keep the injured arm or leg raised above the level of your heart for the first 48 to 72 hours to reduce swelling.'),
  ('DOC015-C3', 'DOC015', 3, 'Cast Care at Home', 'Orthopedics', 'patient_education', '2025-10-10', 'Cast Care at Home. Call the clinic for numbness, tingling, toes or fingers that turn blue or cold, or pain that gets worse when you move them.'),
  ('DOC016-C1', 'DOC016', 1, 'Diabetes Discharge Instructions', 'Endocrinology', 'discharge_instructions', '2026-02-20', 'Diabetes Discharge Instructions. For low blood sugar under 70 mg/dL, use the rule of 15: take 15 grams of fast sugar such as 4 ounces of juice, then recheck in 15 minutes.'),
  ('DOC016-C2', 'DOC016', 2, 'Diabetes Discharge Instructions', 'Endocrinology', 'discharge_instructions', '2026-02-20', 'Diabetes Discharge Instructions. Check your blood sugar before each meal and at bedtime. Write the numbers in your log and bring it to clinic.'),
  ('DOC016-C3', 'DOC016', 3, 'Diabetes Discharge Instructions', 'Endocrinology', 'discharge_instructions', '2026-02-20', 'Diabetes Discharge Instructions. On sick days, keep taking your long-acting (basal) insulin even if you are not eating. Check your sugar every 4 hours.'),
  ('DOC016-C4', 'DOC016', 4, 'Diabetes Discharge Instructions', 'Endocrinology', 'discharge_instructions', '2026-02-20', 'Diabetes Discharge Instructions. See the endocrinology clinic within 2 weeks of discharge.'),
  ('DOC017-C1', 'DOC017', 1, 'Insulin Pen Storage and Use', 'Pharmacy', 'patient_education', '2025-08-01', 'Insulin Pen Storage and Use. Store unopened insulin pens in the refrigerator. Do not freeze them, and throw away any pen that has been frozen.'),
  ('DOC017-C2', 'DOC017', 2, 'Insulin Pen Storage and Use', 'Pharmacy', 'patient_education', '2025-08-01', 'Insulin Pen Storage and Use. An insulin pen you are using can stay at room temperature for up to 28 days. Write the date you opened it on the label.'),
  ('DOC017-C3', 'DOC017', 3, 'Insulin Pen Storage and Use', 'Pharmacy', 'patient_education', '2025-08-01', 'Insulin Pen Storage and Use. Use a new pen needle for every injection and put used needles in a sharps container.'),
  ('DOC018-C1', 'DOC018', 1, 'Inpatient Hypoglycemia Treatment Protocol', 'Nursing', 'care_protocol', '2026-01-15', 'Inpatient Hypoglycemia Treatment Protocol. Treat any blood glucose below 70 mg/dL. If the patient can swallow, give 15 grams of fast-acting carbohydrate.'),
  ('DOC018-C2', 'DOC018', 2, 'Inpatient Hypoglycemia Treatment Protocol', 'Nursing', 'care_protocol', '2026-01-15', 'Inpatient Hypoglycemia Treatment Protocol. If the patient cannot swallow safely, give dextrose 50 percent 25 mL IV, or glucagon 1 mg IM if there is no IV access.'),
  ('DOC018-C3', 'DOC018', 3, 'Inpatient Hypoglycemia Treatment Protocol', 'Nursing', 'care_protocol', '2026-01-15', 'Inpatient Hypoglycemia Treatment Protocol. Recheck glucose every 15 minutes until it is above 100 mg/dL. Notify the provider for any value below 40 mg/dL.'),
  ('DOC019-C1', 'DOC019', 1, 'Fall Prevention Policy (2025 version, superseded)', 'Nursing', 'policy', '2025-01-01', 'Fall Prevention Policy (2025 version, superseded). Score every patient with the Morse Fall Scale on admission and every shift. A score of 45 or higher means high fall risk.'),
  ('DOC019-C2', 'DOC019', 2, 'Fall Prevention Policy (2025 version, superseded)', 'Nursing', 'policy', '2025-01-01', 'Fall Prevention Policy (2025 version, superseded). High fall risk patients get a bed alarm, a yellow wristband and hourly rounding.'),
  ('DOC020-C1', 'DOC020', 1, 'Fall Prevention Policy (2026 version)', 'Nursing', 'policy', '2026-01-01', 'Fall Prevention Policy (2026 version). Score every patient with the Morse Fall Scale on admission, every shift and after any fall. A score of 50 or higher means high fall risk.'),
  ('DOC020-C2', 'DOC020', 2, 'Fall Prevention Policy (2026 version)', 'Nursing', 'policy', '2026-01-01', 'Fall Prevention Policy (2026 version). High fall risk patients get a bed alarm, yellow non-slip socks, a yellow wristband and rounding every hour while awake and every 2 hours overnight.'),
  ('DOC020-C3', 'DOC020', 3, 'Fall Prevention Policy (2026 version)', 'Nursing', 'policy', '2026-01-01', 'Fall Prevention Policy (2026 version). After any fall, hold a post-fall huddle on the unit within 1 hour and file a safety event report before the end of the shift.'),
  ('DOC021-C1', 'DOC021', 1, 'Pressure Injury Prevention Protocol', 'Nursing', 'care_protocol', '2026-02-01', 'Pressure Injury Prevention Protocol. A Braden Scale score of 18 or lower means the patient is at risk for pressure injury.'),
  ('DOC021-C2', 'DOC021', 2, 'Pressure Injury Prevention Protocol', 'Nursing', 'care_protocol', '2026-02-01', 'Pressure Injury Prevention Protocol. Reposition at-risk patients at least every 2 hours. Float the heels off the bed with a pillow under the calves.'),
  ('DOC021-C3', 'DOC021', 3, 'Pressure Injury Prevention Protocol', 'Nursing', 'care_protocol', '2026-02-01', 'Pressure Injury Prevention Protocol. Inspect the skin over the sacrum, heels and elbows at least once each shift and document any redness that does not fade with pressure.'),
  ('DOC022-C1', 'DOC022', 1, 'Discharge Medication Reconciliation Policy', 'Pharmacy', 'policy', '2026-01-10', 'Discharge Medication Reconciliation Policy. A pharmacist reviews the discharge medication list for every patient taking 10 or more medicines, and for every patient on an anticoagulant or insulin.'),
  ('DOC022-C2', 'DOC022', 2, 'Discharge Medication Reconciliation Policy', 'Pharmacy', 'policy', '2026-01-10', 'Discharge Medication Reconciliation Policy. The meds-to-beds program delivers first fills to the bedside before discharge so patients leave with medicines in hand.'),
  ('DOC022-C3', 'DOC022', 3, 'Discharge Medication Reconciliation Policy', 'Pharmacy', 'policy', '2026-01-10', 'Discharge Medication Reconciliation Policy. Any change from the home medication list must have a reason documented in the discharge summary.'),
  ('DOC023-C1', 'DOC023', 1, 'Post-Discharge Follow-up Call Protocol', 'Case Management', 'care_protocol', '2026-03-01', 'Post-Discharge Follow-up Call Protocol. A nurse calls every patient within 48 hours of discharge. Make up to 3 call attempts on different days before closing the outreach.'),
  ('DOC023-C2', 'DOC023', 2, 'Post-Discharge Follow-up Call Protocol', 'Case Management', 'care_protocol', '2026-03-01', 'Post-Discharge Follow-up Call Protocol. During the call, review warning signs, confirm the follow-up appointment and ask the patient to read back each medicine name.'),
  ('DOC023-C3', 'DOC023', 3, 'Post-Discharge Follow-up Call Protocol', 'Case Management', 'care_protocol', '2026-03-01', 'Post-Discharge Follow-up Call Protocol. Patients with a LACE readmission score of 10 or higher must have a primary care visit scheduled within 7 days of discharge.'),
  ('DOC024-C1', 'DOC024', 1, 'Transportation Assistance Policy', 'Case Management', 'policy', '2025-11-01', 'Transportation Assistance Policy. Patients without a ride to a follow-up appointment can get a free ride voucher from case management.'),
  ('DOC024-C2', 'DOC024', 2, 'Transportation Assistance Policy', 'Case Management', 'policy', '2025-11-01', 'Transportation Assistance Policy. Request the ride at least 24 hours before the appointment. Patients with Medicaid are first referred to the non-emergency medical transportation benefit.'),
  ('DOC025-C1', 'DOC025', 1, 'Stroke and TIA Discharge Instructions', 'Neurology', 'discharge_instructions', '2026-01-25', 'Stroke and TIA Discharge Instructions. Learn BE FAST: Balance loss, Eyes (vision change), Face drooping, Arm weakness, Speech trouble, Time to call 911.'),
  ('DOC025-C2', 'DOC025', 2, 'Stroke and TIA Discharge Instructions', 'Neurology', 'discharge_instructions', '2026-01-25', 'Stroke and TIA Discharge Instructions. Your blood pressure goal is below 130/80. Check it at home every day and bring the log to your visits.'),
  ('DOC025-C3', 'DOC025', 3, 'Stroke and TIA Discharge Instructions', 'Neurology', 'discharge_instructions', '2026-01-25', 'Stroke and TIA Discharge Instructions. Take your statin every day, even if your cholesterol numbers look good.'),
  ('DOC025-C4', 'DOC025', 4, 'Stroke and TIA Discharge Instructions', 'Neurology', 'discharge_instructions', '2026-01-25', 'Stroke and TIA Discharge Instructions. See the neurology clinic within 2 weeks. Do not drive until your neurologist clears you.'),
  ('DOC026-C1', 'DOC026', 1, 'Seizure Safety at Home', 'Neurology', 'patient_education', '2025-12-15', 'Seizure Safety at Home. Take showers instead of baths, and do not swim alone.'),
  ('DOC026-C2', 'DOC026', 2, 'Seizure Safety at Home', 'Neurology', 'patient_education', '2025-12-15', 'Seizure Safety at Home. If a seizure lasts more than 5 minutes, or a second seizure starts before the person wakes up, call 911.'),
  ('DOC026-C3', 'DOC026', 3, 'Seizure Safety at Home', 'Neurology', 'patient_education', '2025-12-15', 'Seizure Safety at Home. During a seizure, turn the person on their side, put something soft under their head, and never put anything in their mouth.'),
  ('DOC027-C1', 'DOC027', 1, 'Kidney-Friendly Eating (CKD Diet Education)', 'Nephrology', 'patient_education', '2025-10-20', 'Kidney-Friendly Eating (CKD Diet Education). Avoid pain relievers such as ibuprofen and naproxen. These NSAIDs can harm your kidneys. Acetaminophen is usually safer; ask your doctor.'),
  ('DOC027-C2', 'DOC027', 2, 'Kidney-Friendly Eating (CKD Diet Education)', 'Nephrology', 'patient_education', '2025-10-20', 'Kidney-Friendly Eating (CKD Diet Education). If your potassium is high, limit bananas, oranges, potatoes and tomatoes. Your dietitian will give you a daily target.'),
  ('DOC027-C3', 'DOC027', 3, 'Kidney-Friendly Eating (CKD Diet Education)', 'Nephrology', 'patient_education', '2025-10-20', 'Kidney-Friendly Eating (CKD Diet Education). Take your phosphate binder with meals, not on an empty stomach.'),
  ('DOC028-C1', 'DOC028', 1, 'Contrast Kidney Injury Prevention Protocol', 'Radiology', 'care_protocol', '2026-02-05', 'Contrast Kidney Injury Prevention Protocol. Check eGFR before giving IV contrast to inpatients. For eGFR below 30, give IV normal saline before and after the scan unless the patient has heart failure.'),
  ('DOC028-C2', 'DOC028', 2, 'Contrast Kidney Injury Prevention Protocol', 'Radiology', 'care_protocol', '2026-02-05', 'Contrast Kidney Injury Prevention Protocol. Hold metformin at the time of contrast and for 48 hours after the scan in patients with eGFR below 30, then recheck kidney function before restarting.'),
  ('DOC029-C1', 'DOC029', 1, 'Opioid Safety After Surgery', 'Pharmacy', 'patient_education', '2026-01-30', 'Opioid Safety After Surgery. Do not drink alcohol or take sleeping pills or benzodiazepines while you take opioid pain medicine. The mix can slow or stop your breathing.'),
  ('DOC029-C2', 'DOC029', 2, 'Opioid Safety After Surgery', 'Pharmacy', 'patient_education', '2026-01-30', 'Opioid Safety After Surgery. Opioids cause constipation. Take the stool softener you were prescribed and drink plenty of water.'),
  ('DOC029-C3', 'DOC029', 3, 'Opioid Safety After Surgery', 'Pharmacy', 'patient_education', '2026-01-30', 'Opioid Safety After Surgery. Get rid of leftover opioid pills at a drug take-back site or pharmacy drop box. Ask about a naloxone kit to keep at home.'),
  ('DOC030-C1', 'DOC030', 1, 'Surgical Wound Care Discharge Instructions', 'General Surgery', 'discharge_instructions', '2025-12-05', 'Surgical Wound Care Discharge Instructions. You may shower 48 hours after surgery. Do not soak in a bath, hot tub or pool for 2 weeks.'),
  ('DOC030-C2', 'DOC030', 2, 'Surgical Wound Care Discharge Instructions', 'General Surgery', 'discharge_instructions', '2025-12-05', 'Surgical Wound Care Discharge Instructions. The thin tape strips over your incision will fall off on their own in 7 to 10 days. Do not pull them off.'),
  ('DOC030-C3', 'DOC030', 3, 'Surgical Wound Care Discharge Instructions', 'General Surgery', 'discharge_instructions', '2025-12-05', 'Surgical Wound Care Discharge Instructions. Call your surgeon for redness that spreads, yellow or green drainage, or a fever over 101 F.'),
  ('DOC031-C1', 'DOC031', 1, 'Postpartum Discharge Instructions', 'Obstetrics', 'discharge_instructions', '2026-03-20', 'Postpartum Discharge Instructions. Call your provider or go to the emergency department if you soak through a pad in an hour or pass clots bigger than an egg.'),
  ('DOC031-C2', 'DOC031', 2, 'Postpartum Discharge Instructions', 'Obstetrics', 'discharge_instructions', '2026-03-20', 'Postpartum Discharge Instructions. If you had high blood pressure during pregnancy, get a blood pressure check within 72 hours of going home.'),
  ('DOC031-C3', 'DOC031', 3, 'Postpartum Discharge Instructions', 'Obstetrics', 'discharge_instructions', '2026-03-20', 'Postpartum Discharge Instructions. Severe headache, vision changes or pain under the ribs after delivery can be signs of preeclampsia. Get care right away.'),
  ('DOC032-C1', 'DOC032', 1, 'Visitor Policy', 'Administration', 'policy', '2026-02-15', 'Visitor Policy. Up to 2 visitors may be at the bedside at one time. Quiet hours are 9 p.m. to 6 a.m.'),
  ('DOC032-C2', 'DOC032', 2, 'Visitor Policy', 'Administration', 'policy', '2026-02-15', 'Visitor Policy. Children under 12 must be with an adult who is not the patient.'),
  ('DOC033-C1', 'DOC033', 1, 'Interpreter Services Policy', 'Administration', 'policy', '2025-09-01', 'Interpreter Services Policy. Use a qualified medical interpreter for all clinical conversations with patients who prefer a language other than English. Do not use family members to interpret clinical information.'),
  ('DOC033-C2', 'DOC033', 2, 'Interpreter Services Policy', 'Administration', 'policy', '2025-09-01', 'Interpreter Services Policy. Phone and video interpreters are available 24 hours a day, 7 days a week through the interpreter line.');
INSERT INTO EVAL_QUESTIONS VALUES
  (1, 'How much weight gain in one day should make a heart failure patient call the clinic?', 'DOC001-C1', 'DOC001', 'keyword', NULL),
  (2, 'What is the daily sodium limit for heart failure patients?', 'DOC001-C2', 'DOC001', 'keyword', NULL),
  (3, 'My dad keeps getting up at night to pee after starting his water pill. When should he take it?', 'DOC001-C3', 'DOC001', 'paraphrase', NULL),
