  (5, 'Can I quit my blood thinners after the stent if I feel fine?', 'DOC003-C1', 'DOC003', 'paraphrase', NULL),
  (6, 'How heavy can things be that I pick up with the arm they went in through for the heart procedure?', 'DOC003-C2', 'DOC003', 'paraphrase', NULL),
  (7, 'Chest pain and one nitroglycerin did not help after 5 minutes, what now?', 'DOC003-C3', 'DOC003', 'keyword', NULL),
  (8, 'What INR range is the usual target for atrial fibrillation on warfarin?', 'DOC004-C1', 'DOC004', 'keyword', NULL),
  (9, 'Do I have to stop eating spinach and salad greens on my anticoagulant?', 'DOC004-C2', 'DOC004', 'paraphrase', NULL),
  (10, 'How many days before an operation is warfarin stopped for bridging?', 'DOC005-C1', 'DOC005', 'keyword', NULL),
  (11, 'When is the final dose of the injectable bridge medicine given before the operation?', 'DOC005-C2', 'DOC005', 'paraphrase', NULL),
  (12, 'How long do I take the steroid pills after my lung flare-up?', 'DOC006-C1', 'DOC006', 'paraphrase', NULL),
  (13, 'What does the yellow zone mean on the COPD action plan?', 'DOC006-C3', 'DOC006', 'keyword', NULL),
  (14, 'How far should oxygen be kept from open flames and gas stoves?', 'DOC007-C1', 'DOC007', 'keyword', NULL),
  (15, 'How should I store my oxygen cylinders so they do not tip over?', 'DOC007-C2', 'DOC007', 'paraphrase', NULL),
  (16, 'How often can I use my rescue inhaler before my asthma counts as not well controlled?', 'DOC008-C1', 'DOC008', 'keyword', NULL),
  (17, 'When can pneumonia patients switch from IV to oral antibiotics?', 'DOC009-C1', 'DOC009', 'keyword', NULL),
  (18, 'Which pneumonia patients need a repeat chest x-ray at 6 to 8 weeks?', 'DOC009-C3', 'DOC009', 'keyword', NULL),
  (19, 'How fast must lactate be measured when sepsis is suspected?', 'DOC010-C1', 'DOC010', 'keyword', NULL),
  (20, 'How much IV fluid per kilogram for septic patients with low blood pressure?', 'DOC010-C3', 'DOC010', 'keyword', NULL),
  (21, 'Why is hand sanitizer not enough after caring for a patient with C. diff?', 'DOC011-C2', 'DOC011', 'paraphrase', NULL),
  (22, 'When can contact plus isolation for C. diff be stopped?', 'DOC011-C3', 'DOC011', 'keyword', NULL),
  (23, 'Are fake fingernails allowed for bedside nurses?', 'DOC012-C2', 'DOC012', 'paraphrase', NULL),
  (24, 'After a new hip, which leg positions do I need to avoid and for how long?', 'DOC013-C1', 'DOC013', 'paraphrase', NULL),
  (25, 'How long do patients take aspirin to prevent clots after hip replacement?', 'DOC013-C2', 'DOC013', 'keyword', NULL),
  (26, 'What is the lifting limit after surgery?', 'DOC013-C3', 'DOC013', 'keyword', '{"@eq": {"DEPARTMENT": "Orthopedics"}}'),
  (27, 'How far should my knee bend in the first couple of weeks after the replacement?', 'DOC014-C1', 'DOC014', 'paraphrase', NULL),
  (28, 'How long should the injured limb be raised above the heart after a cast is put on?', 'DOC015-C2', 'DOC015', 'keyword', NULL),
  (29, 'My blood sugar dropped to 62, how many grams of sugar should I eat and when do I check again?', 'DOC016-C1', 'DOC016', 'paraphrase', NULL),
  (30, 'I have the flu and cannot eat. Should I still take my long-acting insulin?', 'DOC016-C3', 'DOC016', 'paraphrase', NULL),
  (31, 'How long can an opened insulin pen stay out of the fridge?', 'DOC017-C2', 'DOC017', 'paraphrase', NULL),
  (32, 'What should the nurse give for low glucose if the patient cannot swallow and has no IV?', 'DOC018-C2', 'DOC018', 'keyword', NULL),
  (33, 'What Morse Fall Scale score means high fall risk?', 'DOC020-C1', 'DOC020', 'keyword', '{"@gte": {"EFFECTIVE_DATE": "2026-01-01"}}'),
  (34, 'How soon must the team meet on the unit after a patient falls?', 'DOC020-C3', 'DOC020', 'paraphrase', NULL),
  (35, 'How often should we turn bedbound patients to prevent bed sores?', 'DOC021-C2', 'DOC021', 'paraphrase', NULL),
  (36, 'Which patients get a pharmacist review of their discharge medication list?', 'DOC022-C1', 'DOC022', 'keyword', NULL),
  (37, 'Within how many hours after going home does a nurse phone the patient?', 'DOC023-C1', 'DOC023', 'paraphrase', NULL),
  (38, 'Which patients need a primary care visit within 7 days based on the LACE score?', 'DOC023-C3', 'DOC023', 'keyword', NULL),
  (39, 'How much notice is needed to book a free ride to a clinic appointment?', 'DOC024-C2', 'DOC024', 'paraphrase', NULL),
  (40, 'What blood pressure goal is given after a stroke?', 'DOC025-C2', 'DOC025', 'keyword', NULL),
  (41, 'When should you call an ambulance for a seizure?', 'DOC026-C2', 'DOC026', 'paraphrase', NULL),
  (42, 'Which over-the-counter pain pills hurt the kidneys?', 'DOC027-C1', 'DOC027', 'paraphrase', '{"@eq": {"DOC_TYPE": "patient_education"}}'),
  (43, 'How long is metformin held after IV contrast for low eGFR?', 'DOC028-C2', 'DOC028', 'keyword', NULL),
  (44, 'What do I do with leftover pain pills after my surgery?', 'DOC029-C3', 'DOC029', 'paraphrase', NULL),
  (45, 'When can I take a bath again after my operation?', 'DOC030-C1', 'DOC030', 'paraphrase', '{"@eq": {"DEPARTMENT": "General Surgery"}}'),
  (46, 'How much bleeding after giving birth is too much?', 'DOC031-C1', 'DOC031', 'paraphrase', NULL),
  (47, 'Can a relative translate for the doctor if they speak both languages?', 'DOC033-C1', 'DOC033', 'paraphrase', NULL),
  (48, 'What is the hospital cafeteria menu on Fridays?', NULL, NULL, 'unanswerable', NULL),
  (49, 'What dose of amoxicillin should a 3 year old child take for an ear infection?', NULL, NULL, 'unanswerable', NULL),
  (50, 'How much does a total knee replacement cost without insurance?', NULL, NULL, 'unanswerable', NULL);
